pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmt > 0);
        vm.assume(withdrawAmt > 0);
        vm.assume(depositAmt <= type(uint256).max / 2);
        vm.assume(withdrawAmt <= depositAmt);

        // Deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        // Withdraw
        address payable adversary = payable(address(new AdversarialWithdrawer(c)));
        vm.deal(adversary, 0);
        vm.prank(adversary);
        c.deposit{value: withdrawAmt}();

        vm.prank(adversary);
        c.withdrawAll();

        // After withdrawal, the contract's balance must equal the sum of credits still owed.
        // Since the adversary withdrew all its credit, only the actor's credit remains.
        // The adversary is a contract that does not hold any credit and has withdrawn everything.
        // The only remaining credit is actor's depositAmt.
        uint256 expectedBalance = depositAmt;
        assertTrue(address(c).balance == expectedBalance);
    }
}

contract AdversarialWithdrawer {
    C public target;
    constructor(C _target) { target = _target; }
    receive() external payable {}
}

