pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 depositAmount, uint96 withdrawAmount, address caller) public {
        // Keep amounts admissible: withdrawal cannot exceed deposit
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(caller != address(0));
        vm.assume(caller.code.length == 0); // EOA for simplicity

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Pre-withdraw partially so the caller later withdraws exactly withdrawAmount, ensuring credit > 0
        // (withdrawAll withdraws all the caller's credit)
        // The deposit gave credit = depositAmount. We withdraw partially by sending to a fresh EOA?
        // Actually with withdrawAll the caller withdraws all their credit directly.
        // We just make a deposit, then call withdrawAll with the same caller.
        // To ensure the condition oCredit > 0, we need credit > 0; deposit ensures that.

        uint creditBefore = c.credit(caller);
        require(creditBefore == depositAmount, "unexpected credit");

        vm.prank(caller);
        c.withdrawAll();

        // After withdrawal, credit MUST be zero (the invariant for correct contract)
        uint creditAfter = c.credit(caller);
        assertTrue(creditAfter == 0);
    }
}

