pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 fuzzSalt) public {
        vm.assume(depositAmount > 0);
        // Generate a caller address deterministically from fuzzSalt so the fuzzer can explore many callers.
        address caller = address(uint160(uint256(keccak256(abi.encode(fuzzSalt)))));
        vm.assume(caller != address(0) && caller != address(this));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        vm.prank(caller);
        try c.withdrawAll() { /* success */ } catch { /* ignore reverts */ }

        // After withdrawAll (whether it reverted or not), the caller's credit must be zero
        // in the reference implementation. The mutant with `credit[msg.sender] = 1` violates this
        // for withdrawals that succeed.
        (bool creditZeroOk, bytes memory creditData) = address(c).call(abi.encodeWithSignature("credit(address)", caller));
        require(creditZeroOk, "credit call failed");
        uint256 creditAfter = abi.decode(creditData, (uint256));
        assertTrue(creditAfter == 0);
    }
}

