pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialCredit, uint256 withdrawAmount, address other) public {
        vm.assume(initialCredit > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= initialCredit);
        vm.assume(other != address(0) && other != address(this) && other != address(c));
        vm.assume(other.balance == 0);

        // Give the actor some initial credit via deposit
        vm.deal(address(this), initialCredit);
        c.deposit{value: initialCredit}();
        uint256 balanceBefore = address(c).balance;
        uint256 myCreditBefore = c.credit(address(this));

        // Withdraw a portion of the credit
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;
        uint256 myCreditAfter = c.credit(address(this));

        // The property: the contract's balance must have decreased by exactly the amount of credit that was cleared.
        // The reference clears all credit, so balanceBefore - balanceAfter == myCreditBefore.
        // The mutant sets credit to 1, so if we deposit again and withdraw, the invariance breaks.
        // We assert the invariant holds after one withdrawal for the reference.
        assertTrue(balanceBefore - balanceAfter == myCreditBefore);
    }
}

