pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;
    function setUp() public { 
        c = new C(); 
        reverter = new Reverter();
    }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // 1. restrict to admissible domain
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        // The reverter should have a credit to trigger the bug; 
        // someone must deposit on its behalf. We'll deposit from address(0x1) and then
        // make the reverter withdraw when it has no code that can succeed.
        address alice = address(0x1);
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        c.deposit{value: depositAmount}();

        // Now move some credit to the reverter contract (which will always fail on receive)
        // by depositing on its behalf
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.deposit{value: depositAmount}();

        uint256 balBefore = address(c).balance;
        // Withdraw from the reverter address — call will fail
        vm.prank(address(reverter));
        c.withdrawAll();

        // After the call, the invariant: contract balance equals sum of all stored credits.
        // We can check via a public mapping getter if any public getter exists.
        // C does not have a public variable for the mapping, but it has a balance variable.
        // The invariant: balance never decreases when a withdrawal fails.
        // For the reference: call fails -> no state change -> balance unchanged.
        // For the mutant: call fails -> balance already subtracted, credit cleared, balance < sum(credits).
        // Since we cannot iterate the mapping, we observe the revert return value.
        // We wrap in try/catch to detect whether the external call succeeded.
        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // The reference returns ok = false, and balance unchanged.
        // The mutant also returns ok = false (because the external call fails),
        // but balance is decreased and credit cleared.
        // We can detect this by checking balance after the failed withdrawal:
        uint256 balAfter = address(c).balance;
        // General rule: if the withdrawal call fails (ok == false), the contract balance must not decrease.
        assertTrue(!ok || balAfter == balBefore);
    }
}

