pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Deploy adversarial helper that always reverts on receive to simulate a failing external call
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), 0);

        // Record credit before the failing withdrawAll attempt
        uint256 preCredit = c.credit(caller);
        assertTrue(preCredit > 0, "credit must be non-zero before withdraw");

        // Cause withdrawAll to be called by the Reverter (which will revert on receive)
        // But we need the caller to be the one with credit, not the helper.
        // So we set the caller's credit high, then call withdrawAll as the caller,
        // but the call destination is the helper contract that reverts on receive.
        // Our adversarial helper will be the caller: this means the helper must have credit.
        // We'll deposit as the helper instead.
        // Actually, we can just deposit as the helper directly to give it credit.
        // Let's redesign: the helper is the caller with credit, and it reverts in receive.
        // That way, withdrawAll sends ETH to helper which reverts.
        // The fuzzer caller is not used; we'll use the helper as the adversarial actor.
        // But we still need fuzzed inputs: we'll keep caller, depositAmount, withdrawAmount.
        // We'll deposit as caller, then transfer credit? No, credit is per-address.
        // Better: we make the helper the fuzzed caller by using its address.
        // Simplify: we deploy the helper and use it as the caller.
        // The caller field now must be the helper's address.
        // We'll still use vm.assume to avoid collisions but it's okay.
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

