pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        // fund the caller and deposit so caller has non-zero credit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        // deploy a reverter that will cause the external call to fail
        Reverter reverter = new Reverter();
        vm.deal(address(c), 0); // balance is already deposited, no extra needed
        // make the reverter a depositor with non-zero credit to test the invariant
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.deposit{value: depositAmount}();
        // record pre-state
        uint256 preBalance = address(c).balance;
        // attempt withdrawAll from the reverter, which will revert on the call
        vm.prank(address(reverter));
        // the reference will revert the entire transaction, mutant will not
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // in the reference, success is false (reverted); in mutant, true
        // after failed attempt, balance must equal total credits (all deposits)
        // we can compute expected total credits: two deposits of depositAmount each
        uint256 expectedTotalCredits = depositAmount * 2;
        // mutant decreased balance but did not clear credit, so balance < expectedTotalCredits
        assertTrue(address(c).balance == expectedTotalCredits || !success);
    }
}

