pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, address user) public {
        // Restrict to admissible domain: user must not be this contract or zero
        vm.assume(user != address(0) && user != address(this));
        // Bound amounts to avoid overflow and ensure enough Ether for deposit
        depositAmt = bound(depositAmt, 1, 1000 ether);
        withdrawAmt = bound(withdrawAmt, 1, depositAmt);
        // Set up user with Ether and prank them for deposit
